WITH root_stats AS ( SELECT root.id, COUNT(child.id) AS reply_total, COALESCE((ARRAY_AGG(child.id ORDER BY child.create_time, child.id) FILTER (WHERE child.id IS NOT NULL))[1], 0) AS first_reply_comment_id FROM t_comment root LEFT JOIN t_comment child ON child.parent_id = root.id AND child.level = 2 WHERE root.id IN
#{rootId}
AND root.level = 1 GROUP BY root.id ) UPDATE t_comment root SET reply_total = stats.reply_total, first_reply_comment_id = stats.first_reply_comment_id, heat = ROUND(COALESCE(root.like_total, 0) * 0.70 + stats.reply_total * 0.30, 2), update_time = CURRENT_TIMESTAMP FROM root_stats stats WHERE root.id = stats.id

